<?php

namespace App\Push;

use App\Models\Device;
use App\Support\Settings;
use Illuminate\Support\Facades\Log;
use Minishlink\WebPush\Subscription;
use Minishlink\WebPush\VAPID;
use Minishlink\WebPush\WebPush;
use Throwable;

/**
 * Browser notifications (Web Push with VAPID). Keys are generated by the
 * server itself: no third-party account is needed.
 */
class WebPushSender
{
    public function __construct(protected Settings $settings) {}

    public function ensureKeys(): void
    {
        if (filled($this->settings->get('webpush.public_key')) && filled($this->settings->get('webpush.private_key'))) {
            return;
        }

        $keys = VAPID::createVapidKeys();
        $this->settings->set(['webpush.public_key' => $keys['publicKey'], 'webpush.private_key' => $keys['privateKey']]);
    }

    public function publicKey(): ?string
    {
        return $this->settings->get('webpush.public_key');
    }

    /**
     * @param  iterable<Device>  $devices
     * @param  array<string, mixed>  $notification  title, body, url, tag, priority
     * @return array<int, ApnsResult>
     */
    public function send(iterable $devices, array $notification): array
    {
        $this->ensureKeys();
        $results = [];

        try {
            $webPush = new WebPush(['VAPID' => [
                'subject' => $this->settings->get('app.url') ?: 'mailto:tocsin@localhost',
                'publicKey' => $this->settings->get('webpush.public_key'),
                'privateKey' => $this->settings->get('webpush.private_key'),
            ]], ['TTL' => 86400, 'urgency' => ($notification['priority'] ?? 3) >= 4 ? 'high' : 'normal']);

            $byEndpoint = [];

            foreach ($devices as $device) {
                $subscription = json_decode((string) $device->web_subscription, true);

                if (! isset($subscription['endpoint']) || ! WebPushEndpoint::allowed($subscription['endpoint'])) {
                    $results[$device->id] = new ApnsResult(410, 'Unregistered');

                    continue;
                }

                $byEndpoint[$subscription['endpoint']] = $device->id;
                $webPush->queueNotification(Subscription::create($subscription), json_encode($notification));
            }

            foreach ($webPush->flush() as $report) {
                $deviceId = $byEndpoint[$report->getEndpoint()] ?? null;

                if ($deviceId === null) {
                    continue;
                }

                // Only the status is kept: the body of the answer is never stored.
                $status = $report->getResponse()?->getStatusCode() ?? 0;
                $results[$deviceId] = $report->isSuccess()
                    ? new ApnsResult(200)
                    : new ApnsResult($report->isSubscriptionExpired() ? 410 : $status, $report->isSubscriptionExpired() ? 'Unregistered' : ($status ? 'HTTP '.$status : 'Push service unreachable'));
            }
        } catch (Throwable $e) {
            Log::warning('Web push failed', ['error' => $e->getMessage()]);
        }

        return $results;
    }
}
